CREATE TABLE roles(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(32) NOT NULL UNIQUE,label VARCHAR(60) NOT NULL);
CREATE TABLE permissions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(60) NOT NULL UNIQUE);
CREATE TABLE users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(50) NOT NULL UNIQUE,email VARCHAR(150) UNIQUE,name VARCHAR(100) NOT NULL,password_hash VARCHAR(255) NOT NULL,active BOOLEAN NOT NULL DEFAULT 1);
CREATE TABLE user_roles(user_id BIGINT UNSIGNED NOT NULL,role_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(user_id,role_id),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(role_id) REFERENCES roles(id));
CREATE TABLE role_permissions(role_id BIGINT UNSIGNED NOT NULL,permission_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(role_id,permission_id),FOREIGN KEY(role_id) REFERENCES roles(id),FOREIGN KEY(permission_id) REFERENCES permissions(id));
CREATE TABLE settings(setting_key VARCHAR(70) PRIMARY KEY,value_json JSON NOT NULL);
CREATE TABLE login_limits(bucket CHAR(64) PRIMARY KEY,attempts INT UNSIGNED NOT NULL,started_at DATETIME(6) NOT NULL);
CREATE TABLE customers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(140) NOT NULL,document_type ENUM('rut','pasaporte','otro') NULL,document VARCHAR(40) NULL,phone VARCHAR(32) DEFAULT '',email VARCHAR(150) DEFAULT '',address VARCHAR(180) DEFAULT '',district VARCHAR(100) DEFAULT '',notes TEXT,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),UNIQUE(document_type,document),INDEX(name),INDEX(phone),INDEX(email));
CREATE TABLE devices(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,customer_id BIGINT UNSIGNED NOT NULL,type VARCHAR(70) NOT NULL,brand VARCHAR(70) DEFAULT '',model VARCHAR(85) DEFAULT '',serial VARCHAR(100) DEFAULT '',os VARCHAR(70) DEFAULT '',notes TEXT,UNIQUE(id,customer_id),FOREIGN KEY(customer_id) REFERENCES customers(id),INDEX(serial));
CREATE TABLE service_orders(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,customer_id BIGINT UNSIGNED NULL,device_id BIGINT UNSIGNED NULL,technician_id BIGINT UNSIGNED NULL,created_by BIGINT UNSIGNED NOT NULL,state ENUM('borrador','recibido','diagnostico','presupuesto_enviado','espera_aprobacion','espera_repuesto','en_reparacion','listo_entrega','entregado','cancelado') NOT NULL DEFAULT 'borrador',priority ENUM('baja','media','alta') NOT NULL DEFAULT 'media',fault TEXT,diagnosis TEXT,condition_notes TEXT,preliminary DECIMAL(18,4) DEFAULT NULL,due_date DATE,received_at DATETIME(6),delivered_at DATETIME(6),created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),version INT UNSIGNED NOT NULL DEFAULT 1,UNIQUE(id,customer_id),FOREIGN KEY(customer_id) REFERENCES customers(id),FOREIGN KEY(device_id,customer_id) REFERENCES devices(id,customer_id),FOREIGN KEY(technician_id) REFERENCES users(id),FOREIGN KEY(created_by) REFERENCES users(id),CHECK(state='borrador' OR (customer_id IS NOT NULL AND device_id IS NOT NULL AND received_at IS NOT NULL)),CHECK(preliminary IS NULL OR preliminary>=0),INDEX(state,received_at),INDEX(technician_id,state),INDEX(due_date,state));
CREATE TABLE service_order_status_history(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,actor_id BIGINT UNSIGNED NOT NULL,from_state VARCHAR(30),to_state VARCHAR(30) NOT NULL,reason VARCHAR(500),occurred_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(order_id) REFERENCES service_orders(id),FOREIGN KEY(actor_id) REFERENCES users(id));
CREATE TABLE service_order_accessories(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,label VARCHAR(160) NOT NULL,FOREIGN KEY(order_id) REFERENCES service_orders(id));
CREATE TABLE service_order_consents(order_id BIGINT UNSIGNED PRIMARY KEY,policy_version VARCHAR(30) NOT NULL,diagnosis_authorized BOOLEAN NOT NULL,accessories_verified BOOLEAN NOT NULL,policy_accepted BOOLEAN NOT NULL,signature_name VARCHAR(140) DEFAULT '',signature_path VARCHAR(70),occurred_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(order_id) REFERENCES service_orders(id));
CREATE TABLE service_order_receipts(order_id BIGINT UNSIGNED PRIMARY KEY,snapshot JSON NOT NULL,FOREIGN KEY(order_id) REFERENCES service_orders(id));
CREATE TABLE service_order_tasks(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,label VARCHAR(200) NOT NULL,progress TINYINT UNSIGNED NOT NULL DEFAULT 0,FOREIGN KEY(order_id) REFERENCES service_orders(id),CHECK(progress<=100));
CREATE TABLE service_order_notes(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,actor_id BIGINT UNSIGNED NOT NULL,note TEXT NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(order_id) REFERENCES service_orders(id),FOREIGN KEY(actor_id) REFERENCES users(id));
CREATE TABLE service_order_photos(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,actor_id BIGINT UNSIGNED NOT NULL,path VARCHAR(80) NOT NULL UNIQUE,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(order_id) REFERENCES service_orders(id),FOREIGN KEY(actor_id) REFERENCES users(id));
CREATE TABLE service_order_secrets(order_id BIGINT UNSIGNED PRIMARY KEY,encrypted VARBINARY(600) NOT NULL,nonce BINARY(24) NOT NULL,expires_at DATETIME(6) NOT NULL,FOREIGN KEY(order_id) REFERENCES service_orders(id),INDEX(expires_at));
CREATE TABLE categories(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(90) NOT NULL UNIQUE);
CREATE TABLE suppliers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL UNIQUE);
CREATE TABLE locations(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(30) NOT NULL UNIQUE,name VARCHAR(120) NOT NULL);
CREATE TABLE products(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,sku VARCHAR(60) NOT NULL UNIQUE,name VARCHAR(150) NOT NULL,description TEXT,category_id BIGINT UNSIGNED NULL,supplier_id BIGINT UNSIGNED NULL,location_id BIGINT UNSIGNED NOT NULL,cost DECIMAL(18,4) NOT NULL DEFAULT 0,price DECIMAL(18,4) NOT NULL,tax_bps SMALLINT UNSIGNED NOT NULL DEFAULT 1900,minimum INT UNSIGNED NOT NULL DEFAULT 0,active BOOLEAN NOT NULL DEFAULT 1,FOREIGN KEY(category_id) REFERENCES categories(id),FOREIGN KEY(supplier_id) REFERENCES suppliers(id),FOREIGN KEY(location_id) REFERENCES locations(id),CHECK(cost>=0 AND price>=0),INDEX(active,name));
CREATE TABLE service_catalog(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(60) NOT NULL UNIQUE,name VARCHAR(150) NOT NULL,cost DECIMAL(18,4) NOT NULL DEFAULT 0,price DECIMAL(18,4) NOT NULL,tax_bps SMALLINT UNSIGNED NOT NULL DEFAULT 1900,active BOOLEAN NOT NULL DEFAULT 1,CHECK(cost>=0 AND price>=0));
CREATE TABLE inventory_balances(product_id BIGINT UNSIGNED NOT NULL,location_id BIGINT UNSIGNED NOT NULL,physical INT UNSIGNED NOT NULL DEFAULT 0,reserved INT UNSIGNED NOT NULL DEFAULT 0,PRIMARY KEY(product_id,location_id),FOREIGN KEY(product_id) REFERENCES products(id),FOREIGN KEY(location_id) REFERENCES locations(id),CHECK(reserved<=physical));
CREATE TABLE pc_projects(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,customer_id BIGINT UNSIGNED NOT NULL,technician_id BIGINT UNSIGNED NULL,device_id BIGINT UNSIGNED NULL,title VARCHAR(150) NOT NULL,type ENUM('nuevo','mejora') NOT NULL,usage_notes TEXT,state ENUM('solicitud','cotizacion','espera_cliente','aprobado','en_armado','pruebas','listo_entrega','entregado','cancelado') NOT NULL DEFAULT 'solicitud',created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),archived_at DATETIME(6),FOREIGN KEY(customer_id) REFERENCES customers(id),FOREIGN KEY(device_id,customer_id) REFERENCES devices(id,customer_id),FOREIGN KEY(technician_id) REFERENCES users(id),INDEX(state,created_at));
CREATE TABLE service_order_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,quantity INT UNSIGNED NOT NULL,UNIQUE(id,product_id),FOREIGN KEY(order_id) REFERENCES service_orders(id),FOREIGN KEY(product_id) REFERENCES products(id),UNIQUE(order_id,product_id),CHECK(quantity>0));
CREATE TABLE pc_project_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,project_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NULL,service_id BIGINT UNSIGNED NULL,quantity INT UNSIGNED NOT NULL,UNIQUE(id,product_id),FOREIGN KEY(project_id) REFERENCES pc_projects(id),FOREIGN KEY(product_id) REFERENCES products(id),FOREIGN KEY(service_id) REFERENCES service_catalog(id),CHECK((product_id IS NULL)<>(service_id IS NULL) AND quantity>0),UNIQUE(project_id,product_id),UNIQUE(project_id,service_id));
CREATE TABLE pc_project_updates(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,project_id BIGINT UNSIGNED NOT NULL,actor_id BIGINT UNSIGNED NOT NULL,kind ENUM('avance','prueba','estado') NOT NULL,note TEXT NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(project_id) REFERENCES pc_projects(id),FOREIGN KEY(actor_id) REFERENCES users(id));
CREATE TABLE product_technical_specs(product_id BIGINT UNSIGNED PRIMARY KEY,component_type VARCHAR(20) NOT NULL,socket VARCHAR(40),ram_type VARCHAR(30),slots INT UNSIGNED,max_ram_gb INT UNSIGNED,module_gb INT UNSIGNED,modules INT UNSIGNED,form_factor VARCHAR(25),supported_formats JSON,length_mm INT UNSIGNED,clearance_mm INT UNSIGNED,power_w INT UNSIGNED,source VARCHAR(220),connectors JSON,bios_status VARCHAR(35),FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE quotes(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NULL,project_id BIGINT UNSIGNED NULL,revision INT UNSIGNED NOT NULL,state ENUM('draft','sent','approved','rejected','superseded') NOT NULL DEFAULT 'draft',valid_until DATE NOT NULL,subtotal DECIMAL(18,4) NOT NULL,tax DECIMAL(18,4) NOT NULL,total DECIMAL(18,4) NOT NULL,created_by BIGINT UNSIGNED NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),sent_at DATETIME(6),send_reference VARCHAR(255),FOREIGN KEY(order_id) REFERENCES service_orders(id),FOREIGN KEY(project_id) REFERENCES pc_projects(id),FOREIGN KEY(created_by) REFERENCES users(id),CHECK((order_id IS NULL)<>(project_id IS NULL)),UNIQUE(order_id,revision),UNIQUE(project_id,revision));
CREATE TABLE quote_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,quote_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NULL,service_id BIGINT UNSIGNED NULL,label VARCHAR(190) NOT NULL,quantity INT UNSIGNED NOT NULL,price DECIMAL(18,4) NOT NULL,discount DECIMAL(18,4) NOT NULL DEFAULT 0,net DECIMAL(18,4) NOT NULL,tax DECIMAL(18,4) NOT NULL,total DECIMAL(18,4) NOT NULL,tax_bps SMALLINT UNSIGNED NOT NULL,FOREIGN KEY(quote_id) REFERENCES quotes(id),FOREIGN KEY(product_id) REFERENCES products(id),FOREIGN KEY(service_id) REFERENCES service_catalog(id),CHECK((product_id IS NULL)<>(service_id IS NULL) AND quantity>0));
CREATE TABLE quote_approvals(quote_id BIGINT UNSIGNED PRIMARY KEY,actor_id BIGINT UNSIGNED NOT NULL,decision ENUM('approved','rejected') NOT NULL,channel VARCHAR(40) NOT NULL,reference VARCHAR(255) NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(quote_id) REFERENCES quotes(id),FOREIGN KEY(actor_id) REFERENCES users(id));
CREATE TABLE cash_registers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(32) NOT NULL UNIQUE,name VARCHAR(100) NOT NULL,active BOOLEAN NOT NULL DEFAULT 1);
CREATE TABLE cash_sessions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,register_id BIGINT UNSIGNED NOT NULL,operator_id BIGINT UNSIGNED NOT NULL,opening DECIMAL(18,4) NOT NULL,opened_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),closed_at DATETIME(6),closed_by BIGINT UNSIGNED,open_register BIGINT UNSIGNED GENERATED ALWAYS AS (IF(closed_at IS NULL,register_id,NULL)) STORED UNIQUE,open_operator BIGINT UNSIGNED GENERATED ALWAYS AS (IF(closed_at IS NULL,operator_id,NULL)) STORED UNIQUE,FOREIGN KEY(register_id) REFERENCES cash_registers(id),FOREIGN KEY(operator_id) REFERENCES users(id),FOREIGN KEY(closed_by) REFERENCES users(id),CHECK(opening>=0));
CREATE TABLE cash_movements(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,session_id BIGINT UNSIGNED NOT NULL,actor_id BIGINT UNSIGNED NOT NULL,direction ENUM('in','out') NOT NULL,amount DECIMAL(18,4) NOT NULL,reason VARCHAR(255) NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(session_id) REFERENCES cash_sessions(id),FOREIGN KEY(actor_id) REFERENCES users(id),CHECK(amount>0));
CREATE TABLE cash_counts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,session_id BIGINT UNSIGNED NOT NULL,actor_id BIGINT UNSIGNED NOT NULL,kind ENUM('partial','close') NOT NULL,expected DECIMAL(18,4) NOT NULL,counted DECIMAL(18,4) NOT NULL,difference DECIMAL(18,4) NOT NULL,summary JSON NOT NULL,notes VARCHAR(500),created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),final_session BIGINT UNSIGNED GENERATED ALWAYS AS (IF(kind='close',session_id,NULL)) STORED UNIQUE,FOREIGN KEY(session_id) REFERENCES cash_sessions(id),FOREIGN KEY(actor_id) REFERENCES users(id));
CREATE TABLE sales(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,customer_id BIGINT UNSIGNED NULL,session_id BIGINT UNSIGNED NOT NULL,actor_id BIGINT UNSIGNED NOT NULL,subtotal DECIMAL(18,4) NOT NULL,tax DECIMAL(18,4) NOT NULL,discount DECIMAL(18,4) NOT NULL,total DECIMAL(18,4) NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),voided_at DATETIME(6),void_reason VARCHAR(255),FOREIGN KEY(customer_id) REFERENCES customers(id),FOREIGN KEY(session_id) REFERENCES cash_sessions(id),FOREIGN KEY(actor_id) REFERENCES users(id),INDEX(created_at,voided_at));
CREATE TABLE sale_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,sale_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NULL,service_id BIGINT UNSIGNED NULL,location_id BIGINT UNSIGNED NULL,label VARCHAR(190) NOT NULL,quantity INT UNSIGNED NOT NULL,price DECIMAL(18,4) NOT NULL,cost DECIMAL(18,4) NOT NULL,discount DECIMAL(18,4) NOT NULL,net DECIMAL(18,4) NOT NULL,tax DECIMAL(18,4) NOT NULL,total DECIMAL(18,4) NOT NULL,tax_bps SMALLINT UNSIGNED NOT NULL,FOREIGN KEY(sale_id) REFERENCES sales(id),FOREIGN KEY(product_id) REFERENCES products(id),FOREIGN KEY(service_id) REFERENCES service_catalog(id),FOREIGN KEY(product_id,location_id) REFERENCES inventory_balances(product_id,location_id),CHECK((product_id IS NULL)<>(service_id IS NULL) AND (product_id IS NULL)=(location_id IS NULL) AND quantity>0));
CREATE TABLE receivables(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NULL UNIQUE,project_id BIGINT UNSIGNED NULL UNIQUE,sale_id BIGINT UNSIGNED NULL UNIQUE,FOREIGN KEY(order_id) REFERENCES service_orders(id),FOREIGN KEY(project_id) REFERENCES pc_projects(id),FOREIGN KEY(sale_id) REFERENCES sales(id),CHECK((order_id IS NOT NULL)+(project_id IS NOT NULL)+(sale_id IS NOT NULL)=1));
CREATE TABLE receivable_terms(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,receivable_id BIGINT UNSIGNED NOT NULL,quote_id BIGINT UNSIGNED NULL UNIQUE,kind ENUM('estimate','firm','void') NOT NULL,amount DECIMAL(18,4) NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(receivable_id) REFERENCES receivables(id),FOREIGN KEY(quote_id) REFERENCES quotes(id),CHECK(amount>=0),INDEX(receivable_id,id));
CREATE TABLE payments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,session_id BIGINT UNSIGNED NOT NULL,actor_id BIGINT UNSIGNED NOT NULL,method ENUM('cash','debit','transfer') NOT NULL,kind ENUM('capture','refund') NOT NULL,amount DECIMAL(18,4) NOT NULL,tendered DECIMAL(18,4),change_due DECIMAL(18,4),reference VARCHAR(155),refund_of_id BIGINT UNSIGNED,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(session_id) REFERENCES cash_sessions(id),FOREIGN KEY(actor_id) REFERENCES users(id),FOREIGN KEY(refund_of_id) REFERENCES payments(id),CHECK(amount>0 AND (kind='refund')=(refund_of_id IS NOT NULL)),INDEX(session_id,method));
CREATE TABLE payment_allocations(payment_id BIGINT UNSIGNED PRIMARY KEY,receivable_id BIGINT UNSIGNED NOT NULL,FOREIGN KEY(payment_id) REFERENCES payments(id),FOREIGN KEY(receivable_id) REFERENCES receivables(id),INDEX(receivable_id,payment_id));
CREATE TABLE stock_reservations(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_item_id BIGINT UNSIGNED NULL,project_item_id BIGINT UNSIGNED NULL,product_id BIGINT UNSIGNED NOT NULL,location_id BIGINT UNSIGNED NOT NULL,initial_qty INT UNSIGNED NOT NULL,active_qty INT UNSIGNED NOT NULL,released_qty INT UNSIGNED NOT NULL DEFAULT 0,consumed_qty INT UNSIGNED NOT NULL DEFAULT 0,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(order_item_id,product_id) REFERENCES service_order_items(id,product_id),FOREIGN KEY(project_item_id,product_id) REFERENCES pc_project_items(id,product_id),FOREIGN KEY(product_id,location_id) REFERENCES inventory_balances(product_id,location_id),CHECK((order_item_id IS NULL)<>(project_item_id IS NULL) AND initial_qty=active_qty+released_qty+consumed_qty AND initial_qty>0));
CREATE TABLE stock_reservation_events(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,reservation_id BIGINT UNSIGNED NOT NULL,actor_id BIGINT UNSIGNED NOT NULL,kind ENUM('created','released','consumed') NOT NULL,quantity INT UNSIGNED NOT NULL,reason VARCHAR(255),created_at DATETIME(6) DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(reservation_id) REFERENCES stock_reservations(id),FOREIGN KEY(actor_id) REFERENCES users(id),CHECK(quantity>0));
CREATE TABLE stock_movements(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id BIGINT UNSIGNED NOT NULL,location_id BIGINT UNSIGNED NOT NULL,actor_id BIGINT UNSIGNED NOT NULL,kind ENUM('entrada','ajuste','salida_venta','consumo','devolucion','reversion') NOT NULL,delta INT NOT NULL,reason VARCHAR(255) NOT NULL,sale_item_id BIGINT UNSIGNED UNIQUE,reservation_event_id BIGINT UNSIGNED UNIQUE,reversal_of_id BIGINT UNSIGNED UNIQUE,returned_from_id BIGINT UNSIGNED,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(product_id,location_id) REFERENCES inventory_balances(product_id,location_id),FOREIGN KEY(actor_id) REFERENCES users(id),FOREIGN KEY(sale_item_id) REFERENCES sale_items(id),FOREIGN KEY(reservation_event_id) REFERENCES stock_reservation_events(id),FOREIGN KEY(reversal_of_id) REFERENCES stock_movements(id),FOREIGN KEY(returned_from_id) REFERENCES stock_movements(id),CHECK(delta<>0));
CREATE TABLE purchase_requests(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,actor_id BIGINT UNSIGNED NOT NULL,reason VARCHAR(255) NOT NULL,state ENUM('pendiente','aprobada','cerrada') NOT NULL DEFAULT 'pendiente',created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(actor_id) REFERENCES users(id));
CREATE TABLE purchase_request_items(request_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,quantity INT UNSIGNED NOT NULL,PRIMARY KEY(request_id,product_id),FOREIGN KEY(request_id) REFERENCES purchase_requests(id),FOREIGN KEY(product_id) REFERENCES products(id),CHECK(quantity>0));
CREATE TABLE appointments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,customer_id BIGINT UNSIGNED NOT NULL,order_id BIGINT UNSIGNED NULL,actor_id BIGINT UNSIGNED NOT NULL,kind ENUM('recepcion','entrega','llamada') NOT NULL,title VARCHAR(180) NOT NULL,scheduled_at DATETIME NOT NULL,state ENUM('pendiente','realizada','cancelada') NOT NULL DEFAULT 'pendiente',FOREIGN KEY(customer_id) REFERENCES customers(id),FOREIGN KEY(order_id,customer_id) REFERENCES service_orders(id,customer_id),FOREIGN KEY(actor_id) REFERENCES users(id),INDEX(scheduled_at,state));
CREATE TABLE audit_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,actor_id BIGINT UNSIGNED NOT NULL,action VARCHAR(80) NOT NULL,order_id BIGINT UNSIGNED NULL,project_id BIGINT UNSIGNED NULL,product_id BIGINT UNSIGNED NULL,sale_id BIGINT UNSIGNED NULL,session_id BIGINT UNSIGNED NULL,customer_id BIGINT UNSIGNED NULL,quote_id BIGINT UNSIGNED NULL,appointment_id BIGINT UNSIGNED NULL,subject_user_id BIGINT UNSIGNED NULL,detail JSON NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(actor_id) REFERENCES users(id),FOREIGN KEY(order_id) REFERENCES service_orders(id),FOREIGN KEY(project_id) REFERENCES pc_projects(id),FOREIGN KEY(product_id) REFERENCES products(id),FOREIGN KEY(sale_id) REFERENCES sales(id),FOREIGN KEY(session_id) REFERENCES cash_sessions(id),FOREIGN KEY(customer_id) REFERENCES customers(id),FOREIGN KEY(quote_id) REFERENCES quotes(id),FOREIGN KEY(appointment_id) REFERENCES appointments(id),FOREIGN KEY(subject_user_id) REFERENCES users(id),CHECK((order_id IS NOT NULL)+(project_id IS NOT NULL)+(product_id IS NOT NULL)+(sale_id IS NOT NULL)+(session_id IS NOT NULL)+(customer_id IS NOT NULL)+(quote_id IS NOT NULL)+(appointment_id IS NOT NULL)+(subject_user_id IS NOT NULL)<=1),INDEX(created_at,id));
CREATE TABLE idempotency_keys(actor_id BIGINT UNSIGNED NOT NULL,scope_key VARCHAR(120) NOT NULL,client_key VARCHAR(96) NOT NULL,payload_hash CHAR(64) NOT NULL,result JSON NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(actor_id,scope_key,client_key),FOREIGN KEY(actor_id) REFERENCES users(id));
